CREATE TABLE IF NOT EXISTS audit.audit_event (recorded_date date NOT NULL, event_id uuid NOT NULL, event_code varchar(100) NOT NULL, occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), request_id varchar(200) NOT NULL, workspace varchar(20), channel varchar(32), authorization_decision varchar(20) NOT NULL, outcome varchar(32) NOT NULL, payload_hash bytea NOT NULL, PRIMARY KEY(recorded_date,event_id), CHECK(octet_length(payload_hash)=32));
CREATE TABLE IF NOT EXISTS audit.audit_event_subject (recorded_date date NOT NULL, event_id uuid NOT NULL, ordinal integer NOT NULL, subject_id uuid NOT NULL, PRIMARY KEY(recorded_date,event_id,ordinal), FOREIGN KEY(recorded_date,event_id) REFERENCES audit.audit_event(recorded_date,event_id) ON DELETE RESTRICT);
